#include <list>
#include <algorithm>
#include <iostream>

void demonstrate_list_remove() {
    std::list<int> l = {1, 2, 3, 2, 4};

    // Correct: Use member function for O(N) link manipulation (fastest)
    l.remove(2); 

    // Incorrect/Inefficient (for list): 
    // auto new_end = std::remove(l.begin(), l.end(), 1);
    // l.erase(new_end, l.end()); 
    // This idiom should be avoided for list, as the member function is superior.

    for (int x : l) {
        std::cout << x << " "; // Output: 1 3 4
    }
}
